<div class="table-scroll"><table><caption class="sr-only"><?= $role === 'vendedor' ? 'Productos publicados de ejemplo de Tienda Volcán' : 'Productos de demostración' ?></caption><thead><tr><th>Producto</th><?php if ($role === 'administrador'): ?><th>Vendedor</th><?php endif; ?><th class="number">Precio</th><th>Stock</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><span class="table-product"><img src="/assets/img/<?= e($product['image']) ?>" width="36" height="36" alt=""><span><?= e($product['name']) ?></span></span></td><?php if ($role === 'administrador'): ?><td class="muted">Tienda Volcán</td><?php endif; ?><td class="number"><?= money($product['cents']) ?></td><td><span class="badge <?= $product['stock'] < 10 ? 'warning' : '' ?>"><?= e($product['stock']) ?></span></td><td><div class="table-actions"><button class="text-button" type="button" data-edit-product data-name="<?= e($product['name']) ?>" data-description="<?= e($product['description']) ?>" data-price="<?= e($product['cents']/100) ?>" data-stock="<?= e($product['stock']) ?>" data-image="<?= e($product['image']) ?>">Editar<span class="sr-only"> <?= e($product['name']) ?></span></button><?php if ($role === 'administrador'): ?><button class="text-button danger" type="button" data-notice="Eliminar productos requiere el backend de fase 3. Ningún producto se ha eliminado.">Eliminar<span class="sr-only"> <?= e($product['name']) ?></span></button><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div>
